import{_ as e,o as a,c as d,a2 as n}from"./chunks/framework.CFuv5BrO.js";const p=JSON.parse('{"title":"Day07 · Goal evidence, delegation, and personal context","description":"","frontmatter":{"title":"Day07 · Goal evidence, delegation, and personal context","outline":false},"headers":[],"relativePath":"en/log/day-07.md","filePath":"en/log/day-07.md","lastUpdated":1794305977000}'),o={name:"en/log/day-07.md"};function i(r,t,s,l,c,u){return a(),d("div",null,[...t[0]||(t[0]=[n('<p>2026-11-10 moved Hearth from &quot;tasks can run&quot; toward &quot;tasks have contracts, handoffs, context, and acceptance evidence&quot;. 56 commits touched 522 files (+20,709/−52,818): the first half added goal budgets, deadlines, stop conditions, command and Git validators, approval action binding, and reconciliation for uncertain effects; the second half added durable delegation, sandboxing, handoff evidence, channel idempotency, the personal ontology, Context Broker, standing intents, and connection runtime, then moved the evaluation corpus, apps, and scenario runner out of the main repository.</p><p>The large deletion count comes mainly from moving the evaluation stack and decoupling templates, not from removing product capability. The main repository keeps the evaluation bridge, task templates, product service, and operating evidence; evaluation cases, console, experiments, and scenario evidence now live in a standalone repository.</p><h2 id="goal-and-completion-evidence" tabindex="-1">Goal and completion evidence <a class="header-anchor" href="#goal-and-completion-evidence" aria-label="Permalink to &quot;Goal and completion evidence&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Result</th></tr></thead><tbody><tr><td>Budgets and stop</td><td>Goal budgets cover turns, tool calls, tokens, duration, and human minutes; deadlines, stop conditions, and review policy enter scheduling, and exhaustion pauses, degrades, or hands work to a person</td></tr><tr><td>Validators</td><td>Completion judgement adds command and Git validators alongside file, schema, human, and model review; commands run in a restricted environment and cannot expand authority</td></tr><tr><td>Scheduler</td><td>The scheduler injects custom validators when a task is ready to finish and persists the completion report; goal tasks cannot close without a verdict</td></tr><tr><td>Handoff evidence</td><td>Terminal evidence survives executor handoff, and late results from an old generation cannot overwrite new state</td></tr><tr><td>Interface</td><td>Task detail shows criteria, completion verdict, evidence, and missing items instead of only an executor summary</td></tr></tbody></table><h2 id="delegation-handoff-and-sandboxing" tabindex="-1">Delegation, handoff, and sandboxing <a class="header-anchor" href="#delegation-handoff-and-sandboxing" aria-label="Permalink to &quot;Delegation, handoff, and sandboxing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Result</th></tr></thead><tbody><tr><td>Durable delegation</td><td>A parent creates bounded child tasks with budget, workspace policy, parent-child relation, lease, heartbeat, and failure state; the scheduler advances them</td></tr><tr><td>Workspace policy</td><td>Read-only, isolated-write, and shared-read policies bound what children can see and write</td></tr><tr><td>Sandbox</td><td>Checks working directory, read/write paths, network hosts, process allowlist, and credential boundaries; any violation fails closed with a reason</td></tr><tr><td>Handoff packet</td><td>Records goal, next action, acceptance criteria, evidence, permission subset, context watermark, generation, and redaction; work resumes only after verification</td></tr><tr><td>Channel idempotency</td><td>Feishu and other channel ingress events deduplicate by identity, so repeat delivery cannot create two tasks, approvals, or child tasks</td></tr></tbody></table><h2 id="personal-context-and-attention" tabindex="-1">Personal context and attention <a class="header-anchor" href="#personal-context-and-attention" aria-label="Permalink to &quot;Personal context and attention&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Result</th></tr></thead><tbody><tr><td>Personal ontology</td><td>Entities, aliases, relations, states, decisions, and commitments become shared records; conflicting states are not silently overwritten but become attention items</td></tr><tr><td>Context Broker</td><td>Assembles context packs for chat, task, goal, handoff, and delegation scopes into must-know, relevant, recallable, and omitted lanes; references can expand only within parent authority</td></tr><tr><td>Memory governance</td><td>Source, confidence, taint, sensitivity, and validity affect recall; consolidation is auditable, and forgetting propagates to projections, versions, events, sync, and derived memory</td></tr><tr><td>Standing intents</td><td>Long-lived user rules become standing intents; a heartbeat turns intent and task state into candidates that explain why now, the next action, and the consequence of ignoring</td></tr><tr><td>Attention budget</td><td>Daily limit, quiet hours, per-kind cooldown, per-goal and high-priority limits, ignored penalty, and <code>NO_REPLY</code> feedback regulate interruption</td></tr><tr><td>Connection runtime</td><td>Transport, subscription, data freshness, and execution ownership are separate; reconnect advances generation, old-generation writes are rejected, offline actions enter an outbox, and cached projections never pretend to be live</td></tr></tbody></table><h2 id="approvals-skills-and-scheduling-boundaries" tabindex="-1">Approvals, skills, and scheduling boundaries <a class="header-anchor" href="#approvals-skills-and-scheduling-boundaries" aria-label="Permalink to &quot;Approvals, skills, and scheduling boundaries&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Result</th></tr></thead><tbody><tr><td>Approval binding</td><td>Native patch, full-permission actions, GitHub writes, and SMTP sends bind the resolved real action; changed parameters, expiry, and reuse invalidate approval</td></tr><tr><td>Uncertain effects</td><td>External actions with uncertain delivery enter an explicit reconciliation queue where the user can confirm, retry, or abandon instead of blindly resending</td></tr><tr><td>Skill permissions</td><td>Skills are scoped by usage source, permission range, and risk; stale skills can be curated with rollback</td></tr><tr><td>Schedule catch-up</td><td>Scheduled tasks support bounded catch-up and failure cooldown so downtime or repeated failure cannot flood execution</td></tr><tr><td>Tests</td><td>Added regressions for goals, completion, delegation, handoff, sandbox, channels, connections, ontology, Context Broker, attention, and approval binding</td></tr></tbody></table><h2 id="evaluation-split-and-documentation" tabindex="-1">Evaluation split and documentation <a class="header-anchor" href="#evaluation-split-and-documentation" aria-label="Permalink to &quot;Evaluation split and documentation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Result</th></tr></thead><tbody><tr><td>Standalone evaluation</td><td>Evaluation web, service, core, cases, scenario runner, and docs moved to <code>hearth-eval</code>; the main repository keeps only task/judge bridge contracts and the managed artifact directory</td></tr><tr><td>Template decoupling</td><td>Product task templates no longer depend on the evaluation corpus; the product service owns its example inputs and output declarations</td></tr><tr><td>Artifact roots</td><td>Task artifacts land under the product artifact root, while evaluation inputs are authorized through an external root</td></tr><tr><td>Documentation facts</td><td>README, delivery status, executor handoff, evaluation guide, and phase notes now describe the split; this page and Day06 are added</td></tr></tbody></table><h2 id="commits" tabindex="-1">Commits <a class="header-anchor" href="#commits" aria-label="Permalink to &quot;Commits&quot;">​</a></h2><h3 id="_2026-11-10-56-commits-selected" tabindex="-1">2026-11-10 (56 commits, selected) <a class="header-anchor" href="#_2026-11-10-56-commits-selected" aria-label="Permalink to &quot;2026-11-10 (56 commits, selected)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Commit</th><th>Author</th><th>Changes</th></tr></thead><tbody><tr><td><code>753804b</code></td><td>JasonBuildAI</td><td>Enforced goal budgets for turns, tools, tokens, duration, and human minutes, with deadlines and stop conditions; 4 files (+279/−20).</td></tr><tr><td><code>442db1d</code></td><td>JasonBuildAI</td><td>Added command and Git validators to completion judgement for tests, diffs, and workspace evidence; 2 files (+165/−2).</td></tr><tr><td><code>93c3608</code></td><td>JasonBuildAI</td><td>Injected custom validators from the scheduler and persisted completion reports; 2 files (+73/−2).</td></tr><tr><td><code>0c778d1</code></td><td>JasonBuildAI</td><td>Showed criteria, completion verdict, and missing evidence in task detail; multiple files.</td></tr><tr><td><code>47c9517</code></td><td>JasonBuildAI</td><td>Bound native patch and full-permission actions to the resolved real action so changed parameters invalidate approval; 3 files (+144/−24).</td></tr><tr><td><code>4e73449</code></td><td>JasonBuildAI</td><td>Exposed the reconciliation queue and manual handling for uncertain effects; 10 files (+394/−9).</td></tr><tr><td><code>61c849d</code></td><td>JasonBuildAI</td><td>Added durable single-layer delegation with budget, workspace policy, parent-child relation, and failure state; 2 files (+695).</td></tr><tr><td><code>2a232e8</code></td><td>JasonBuildAI</td><td>Enforced path, network, and credential sandbox boundaries and failed closed on escape; 2 files (+249).</td></tr><tr><td><code>90920ba</code></td><td>JasonBuildAI</td><td>Validated handoff generations and persisted handoff evidence so old-generation results cannot overwrite new state; 7 files (+1,109/−15).</td></tr><tr><td><code>be5112d</code></td><td>JasonBuildAI</td><td>Persisted Feishu ingress idempotency so repeat delivery does not create duplicate tasks or approvals; 3 files (+177/−35).</td></tr><tr><td><code>4bb5b1d</code></td><td>JasonBuildAI</td><td>Added the personal ontology, Context Broker, and attention runtime; 51 files (+7,840/−140).</td></tr><tr><td><code>4e0ecce</code></td><td>JasonBuildAI</td><td>Added standing intents, heartbeat, and an attention queue governed by budget and feedback; 7 files (+1,607/−3).</td></tr><tr><td><code>32877f2</code></td><td>JasonBuildAI</td><td>Added generation-owned connection runtime, offline outbox, and cached projections; 9 files (+1,475/−5).</td></tr><tr><td><code>5a7ece2</code></td><td>JasonBuildAI</td><td>Curated stale skills with rollback; 7 files (+628/−8).</td></tr><tr><td><code>d43941d</code></td><td>JasonBuildAI</td><td>Enforced scoped skill permissions; 7 files (+781/−7).</td></tr><tr><td><code>8dbc39f</code></td><td>JasonBuildAI</td><td>Added bounded catch-up and failure cooldown for schedules; 5 files (+785/−58).</td></tr><tr><td><code>89df4e7</code></td><td>JasonBuildAI</td><td>Moved the evaluation corpus and scenario runner out of the main repository; 259 files (−42,941).</td></tr><tr><td><code>cb097b9</code></td><td>JasonBuildAI</td><td>Moved evaluation web, service, and core out of the main repository; 49 files (−8,859).</td></tr><tr><td><code>f14642c</code></td><td>JasonBuildAI</td><td>Decoupled product task templates from the evaluation corpus; 2 files (+39/−112).</td></tr></tbody></table><h2 id="boundaries-and-next-step" tabindex="-1">Boundaries and next step <a class="header-anchor" href="#boundaries-and-next-step" aria-label="Permalink to &quot;Boundaries and next step&quot;">​</a></h2><ul><li>Completion judgement covers commands, files, schema, Git, human, and model review, but subjective quality, real business impact, and real external receipts still need human acceptance.</li><li>Delegation is single-layer with no recursive agent team. The local sandbox checks paths, network, processes, and credentials; it is not a strong container or VM boundary.</li><li>The connection runtime has generations, an offline outbox, and cached projections, but no real remote node or phone, and no real offline-reconnect or cross-node reconciliation acceptance.</li><li>The personal ontology and Context Broker still rely mainly on local heuristic matching and ranking. Real long-term personal data, phone push, remote takeover, and cross-device context consistency remain unaccepted.</li><li>The evaluation stack is standalone, but this documentation update did not produce real experiments or pass rates in <code>hearth-eval</code>; main-repository tests do not replace independent evaluation.</li><li><code>npm test</code> on the same day: 89 test files and 579 tests passed; <code>npm run typecheck</code>, <code>npm run build</code>, and <code>npm run docs:build</code> passed. Passing tests are not real-user, real-device, or long-running acceptance.</li></ul>',17)])])}const m=e(o,[["render",i]]);export{p as __pageData,m as default};
